// Web -> FS (catálogo) con UPSERT por referencia: crea si no existe, actualiza si existe.
// Nunca duplica. Hace una pausa entre llamadas para no provocar el 429 de FacturaScripts.
const FS_BASE   = 'http://127.0.0.1/api/3';
const FS_TOKEN  = 'PON_TU_TOKEN_FS';
const WEB_URL   = 'http://127.0.0.1:3000/api/sync/products';
const WEB_SECRET = 'PON_TU_SECRETO_SYNC';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const enc = (o) => Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');

// 1) Catálogo de la web (solo productos CON SKU)
const web = await this.helpers.httpRequest({
  method: 'GET', url: WEB_URL,
  headers: { 'X-Sync-Secret': WEB_SECRET }, json: true,
});
const productos = (web.products || []).filter((p) => p.sku && String(p.sku).trim() !== '');

const resumen = [];
for (const p of productos) {
  const ref = String(p.sku).trim();
  const body = {
    referencia: ref,
    descripcion: p.name,
    precio: Math.round((p.price / 1.21) * 100) / 100,
    codimpuesto: 'IVA21',
    codfamilia: String(p.category_slug || 'varios').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8),
    sevende: 1,
    secompra: 0,
  };
  try {
    // ¿existe ya en FS por referencia?
    const found = await this.helpers.httpRequest({
      method: 'GET',
      url: FS_BASE + '/productos?filter[referencia]=' + encodeURIComponent(ref) + '&limit=1',
      headers: { 'X-Auth-Token': FS_TOKEN }, json: true,
    });
    const lista = Array.isArray(found) ? found : (found.data || []);
    if (lista.length && lista[0].idproducto) {
      await this.helpers.httpRequest({
        method: 'PUT',
        url: FS_BASE + '/productos/' + lista[0].idproducto,
        headers: { 'X-Auth-Token': FS_TOKEN, 'Content-Type': 'application/x-www-form-urlencoded' },
        body: enc(body),
      });
      resumen.push({ json: { referencia: ref, accion: 'actualizado', id: lista[0].idproducto } });
    } else {
      await this.helpers.httpRequest({
        method: 'POST',
        url: FS_BASE + '/productos',
        headers: { 'X-Auth-Token': FS_TOKEN, 'Content-Type': 'application/x-www-form-urlencoded' },
        body: enc(body),
      });
      resumen.push({ json: { referencia: ref, accion: 'creado' } });
    }
  } catch (e) {
    resumen.push({ json: { referencia: ref, accion: 'error', error: String((e && e.message) || e) } });
  }
  await sleep(1500); // pausa anti-429
}
return resumen.length ? resumen : [{ json: { info: 'sin productos con SKU' } }];
